const EST_BASE={"Plumbing":[250,900],"Electrical":[200,1100],"HVAC":[300,1600],"Roofing":[600,4500],"Carpentry":[400,2500],"Remodeling":[6000,22000],"Concrete & Masonry":[1200,5500],"Painting":[500,2800],"Flooring":[1500,5200],"Landscaping":[400,2600],"Snow Removal":[45,180],"Excavation":[1500,7000],"Decks & Docks":[2500,9000],"Fencing":[1500,5000],"Siding & Exterior":[1500,9000],"Insulation":[900,3500],"Cleaning":[150,450],"Handyman":[120,450],"Appliance Repair":[120,450],"Pest Control":[150,650],"Moving & Hauling":[250,1200],"Auto & Marine":[150,800],"Welding & Metal":[250,1500],"Pools & Hot Tubs":[300,2200],"Security & Smart Home":[250,1500],"Well & Water":[500,4500],"Countertops":[1800,4800],"Windows & Glass":[400,2400],"Inspection":[300,650],"Property Management":[60,250],"Drywall & Plaster":[300,1800],"Solar & Energy":[8000,22000]};
const EST_SIZE={small:[.5,"Small / single fix"],medium:[1,"Medium / one room or area"],large:[1.9,"Large / several rooms"],major:[3.4,"Major / whole home"]};
const EST_URG={flexible:[.95,"Flexible (2+ weeks)"],soon:[1,"This week"],urgent:[1.2,"Within 48 hours"],emergency:[1.55,"Emergency / after hours"]};
const EST_REGION={"NY":1.32,"MA":1.25,"CA":1.22,"WA":1.16,"DC":1.2,"OR":1.08,"IL":1.08,"CO":1.06,"NV":1.02,"MN":1.04,"ME":1.02,"UT":1,"AZ":.97,"TX":.96,"FL":.97,"GA":.95,"NC":.94,"SC":.93,"TN":.93,"OH":.92,"MI":.95,"IN":.91,"KY":.9,"AL":.88,"OK":.88,"MO":.92,"NE":.92,"NM":.93,"ID":.97,"MT":.98,"LA":.92,"PA":1.04,"WI":.97};
const EST_KW=[[/two[- ]?stor|2[- ]?stor|second floor|steep/,1.15,"Height / access (multi-story or steep)"],[/permit|inspection|code/,1.08,"Permit & inspection"],[/old|historic|19[0-6]\d|knob|lead paint|asbestos/,1.12,"Older home conditions"],[/replace|replacement|new install|install new/,1.1,"Full replacement"],[/repair|fix|patch|small leak/,.88,"Repair rather than replace"],[/premium|high[- ]end|custom|quartz|stone/,1.18,"Premium materials"],[/mold|rot|water damage|structural/,1.15,"Hidden damage risk"]];
function estimateRange(o){o=o||{};const cat=EST_BASE[o.cat]?o.cat:"Handyman";const [b0,b1]=EST_BASE[cat];const sz=EST_SIZE[o.size]||EST_SIZE.medium,ur=EST_URG[o.urg]||EST_URG.soon;const st=ZIPS[o.zip]?ZIPS[o.zip][0].slice(-2):"";const rg=EST_REGION[st]||1;const d=String(o.desc||"").toLowerCase();
 const f=[{k:"Base range for "+cat,v:money(b0)+"–"+money(b1)},{k:"Size: "+sz[1],x:sz[0]},{k:"Urgency: "+ur[1],x:ur[0]},{k:"Regional cost index"+(st?" ("+st+")":""),x:rg}];
 let m=sz[0]*ur[0]*rg;EST_KW.forEach(([re,x,t])=>{if(re.test(d)){m*=x;f.push({k:"From your description: "+t,x})}});
 const rd=n=>n<1000?Math.round(n/10)*10:Math.round(n/50)*50;return{cat,low:rd(b0*m),high:rd(b1*m),mult:Math.round(m*100)/100,factors:f}}

