 releaseMilestone(jid,mid){const m=me(),j=mineJob(jid);if(!m||!j||j.cust!==m.id)return{ok:false,msg:"Only the customer can sign off"};const x=j.escrow&&j.escrow.ms.find(y=>y.id===mid);if(!x||!["funded","requested"].includes(x.status))return{ok:false,msg:"Fund this milestone first"};x.status="released";x.relAt=Date.now();notify(j.hired,`Signed off: ${x.title}. ${money(x.amount)} released (test mode)`,"job:"+jid);save();return{ok:true,msg:"Signed off. Released in test mode."}},
