function crewSuggest(p,r){const taken=new Set(p.roles.flatMap(x=>[...x.filled,...(x.invites||[]).filter(i=>i.status==="invited").map(i=>i.cid)]));
 const all=PROS().filter(u=>u.trade===r.trade&&!taken.has(u.id)&&u.id!==p.pm).map(u=>({u,d:dist(p.zip,u.zip),r:rating(u.id),busy:p.start&&p.end?proBusy(u.id,p.start,p.end,p.id):null})).filter(x=>x.d<=Math.max(150,+x.u.radius||0));
 const sc=x=>(isRapid(x.u.id)?2:0)+x.r.avg*Math.log(2+x.r.n)/3-x.d/120;return{avail:all.filter(x=>!x.busy).sort((a,b)=>sc(b)-sc(a)),busy:all.filter(x=>x.busy)}}

